// 正规Installed目录进入真实世界；仅负向分支改坏冷候选，正向雨损与届满均由原半日推进产生。
#include "resident/kernel/boundary_dispatch.hpp"
#include "resident/storage/common_codec.hpp"
#include "resident/kernel/world_codec.hpp"
#include "resident/kernel/native_initial_state.hpp"
#include "resident/checkpoint/checkpoint_selection.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
using V=BoundaryValue;namespace fs=std::filesystem;Integer checks=0;V::Array trace;
// Release也保留逐门检查，原拒绝不被空默认值覆盖。
void check(bool value,const StableId& why){++checks;if(!value)throw std::runtime_error(why);}
template<class T>T need(Outcome<T> value,const StableId& why){check(value.ok,why+": "+value.error.original.code);return std::move(value.value);}
const V& field(const V& value,const StableId& key){return boundary::field(value,key,"probe");}
StableId text(const V& value,const StableId& key){return boundary::get_string(value,key,"probe");}
Integer number(const V& value,const StableId& key){return boundary::get_int(value,key,"probe");}
StableId json(const V& value){return need(render_boundary_json(value),"render evidence");}
V read(const fs::path& path){std::ifstream in(path);check(bool(in),"open input");std::ostringstream data;data<<in.rdbuf();return need(parse_boundary_json(data.str()),"parse input");}
void write(const fs::path& path,const V& value){std::ofstream out(path);check(bool(out),"open evidence");out<<json(value)<<'\n';}
void set(V& value,const StableId& key,V replacement){for(auto& row:*value.as<V::Dict>())if(row.first==key){row.second=std::move(replacement);return;}throw std::runtime_error("missing mutation key "+key);}
void erase(V& value,const StableId& key){auto& rows=*value.as<V::Dict>();rows.erase(std::remove_if(rows.begin(),rows.end(),[&](const auto& row){return row.first==key;}),rows.end());}
// 实际command_context提供本人请求序与版本；探针不伪造职权或授予世界资源。
V query(ResidentReplaySession& world,const StableId& id,const V& args=boundary::obj({})){return need(world.execute_live({LiveOperationKind::query,need(world.identity(),"query identity"),boundary::obj({{"query_id",V{id}},{"args",args}})}),"query "+id).result;}
Outcome<LiveOperationResult> command(ResidentReplaySession& world,const StableId& kind){auto context=query(world,"command_context");return world.execute_live({LiveOperationKind::command,need(world.identity(),"command identity"),boundary::obj({{"kind",V{kind}},{"params",boundary::obj({})},{"actor_id",field(context,"actor_id")},{"request_seq",field(context,"next_request_seq")},{"expected_revision",field(context,"revision")}})});}
void submit(ResidentReplaySession& world,const StableId& kind){auto result=need(command(world,kind),"submit "+kind).result;trace.push_back(result);check(boundary::get_bool(result,"ok","receipt"),"command rejected "+json(result));}
V exported(ResidentReplaySession& world){return need(world.export_state(),"export state");}
Bytes save(ResidentReplaySession& world,const fs::path& root,const StableId& name){auto bytes=need(world.checkpoint(),"checkpoint");std::ofstream out(root/(name+".bank"),std::ios::binary);out.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());check(bool(out),"save bank");write(root/(name+".json"),exported(world));return bytes;}
// 只核本域实际付款涉及的钱包；NPC原行旅耗费不误报成生产增减钱。
void money_conserved(const V& initial,const V& final){std::map<StableId,Integer> deltas;for(const auto& row:boundary::object(field(field(final,"local_economy"),"payments"),"payments")){const auto& receipt=row.second;deltas[text(receipt,"from_wallet_id")]-=number(receipt,"amount");deltas[text(receipt,"to_wallet_id")]+=number(receipt,"amount");}for(const auto& row:deltas)check(number(field(field(final,"wallets"),row.first),"balance")-number(field(field(initial,"wallets"),row.first),"balance")==row.second,"actual wage source/payee conservation "+row.first);}
// 全部本域输入、输出与口粮均按真实收据核原容器；减产损失不是多消耗或额外退款。
Integer quantity(const V& state,const StableId& inventory,const StableId& item){Integer total=0;for(const auto& lot:boundary::array(field(field(field(state,"inventories"),inventory),"lots"),"lots"))if(text(lot,"item_id")==item)total+=number(lot,"quantity");return total;}
void materials_conserved(const V& initial,const V& final){std::map<std::pair<StableId,StableId>,Integer> deltas;const auto& economy=field(final,"local_economy");for(const auto& row:boundary::object(field(economy,"production_receipts"),"production")){for(const auto& input:boundary::array(field(row.second,"inputs"),"inputs"))deltas[{text(input,"inventory_id"),text(input,"item_id")}]-=number(input,"quantity");for(const auto& output:boundary::array(field(row.second,"outputs"),"outputs"))deltas[{text(output,"inventory_id"),text(output,"item_id")}]+=number(output,"quantity");}for(const auto& row:boundary::object(field(economy,"rations"),"rations"))deltas[{text(row.second,"inventory_id"),text(row.second,"item_id")}]-=number(row.second,"consumed");for(const auto& row:deltas)check(quantity(final,row.first.first,row.first.second)-quantity(initial,row.first.first,row.first.second)==row.second,"actual material balance "+row.first.first);}
// 原页公开的机构authority才用于有限查询，纯读不推世界或增事实。
V page(ResidentReplaySession& world){auto location=query(world,"journey_location");auto args=boundary::obj({{"place_id",field(location,"place_id")}});auto initial=query(world,"local_economy",args);const auto& authorities=boundary::array(field(initial,"authorities"),"authorities");if(!authorities.empty())args.as<V::Dict>()->emplace_back("authority",authorities.front());return query(world,"local_economy",args);}
}
int main(int argc,char** argv){fs::path root;try{
 check(argc==4,"usage: production_disruption_live_probe CATALOG NATIVE_REQUEST OUTPUT");root=argv[3];fs::create_directories(root);const auto catalog=read(argv[1]),request=read(argv[2]);check(text(request,"scenario_id")=="disruption::scenario.qingchuan_production_disruption","original authored scenario required");
 auto world=create_resident_replay_session();auto initialized=world->initialize_native(catalog,request);check(initialized.ok,"native new world: "+initialized.error.original.code);const auto initial=exported(*world);save(*world,root,"initial");
 V before_due;Bytes before_due_bank;Integer last_step_ids=0;
 while(need(world->identity(),"tick").tick<12){const auto tick=need(world->identity(),"before wait").tick;submit(*world,"wait");if(need(world->identity(),"wait result").tick==tick){if(tick==3){before_due=exported(*world);before_due_bank=need(world->checkpoint(),"original pre-production bank");}const auto before=exported(*world);submit(*world,"advance");if(tick==3)last_step_ids=number(exported(*world),"next_instance_id")-number(before,"next_instance_id");}check(need(world->identity(),"after halfday").tick==tick+1,"exactly one halfday");if(tick==3||tick==7||tick==11)save(*world,root,"tick-"+std::to_string(tick+1));}
 const auto final=exported(*world);money_conserved(initial,final);materials_conserved(initial,final);const auto& losses=boundary::object(field(field(final,"production_disruptions"),"settlements"),"settlements");check(losses.size()==2,"two closed-window affected cycles");
 for(const auto& row:losses){const auto& value=row.second;check(number(value,"due_tick")==4||number(value,"due_tick")==8,"only ticks4/8 reduced");check(number(value,"remaining_yield_bp")==5000,"actual authored remaining yield");for(const auto& output:boundary::array(field(value,"outputs"),"outputs")){check(number(output,"original_potential")==number(output,"unproduced")+number(output,"adjusted_potential"),"loss conservation");check(number(output,"adjusted_potential")==number(output,"stored")+number(output,"capacity_shortfall"),"stored/capacity conservation");}}
 const auto& economy=field(final,"local_economy");bool expired=false;for(const auto& row:boundary::object(field(economy,"production_receipts"),"production_receipts")){const auto& receipt=row.second;if(text(receipt,"unit_id")=="production.city"&&number(receipt,"due_tick")==12){expired=true;Integer total=0;for(const auto& output:boundary::array(field(receipt,"outputs"),"outputs"))total+=number(output,"quantity");check(total==4,"expiry resumes original output without catchup");}}check(expired,"real post-expiry production receipt");
 auto bank=save(*world,root,"final");auto cold=create_resident_replay_session();auto restored=cold->initialize_checkpoint(catalog,bank);check(restored.ok,"independent cold install: "+restored.error.original.code);check(bank==need(cold->checkpoint(),"cold checkpoint"),"complete bank exact cold roundtrip");
 const auto envelope=need(inspect_checkpoint_selected(bank,checkpoint_domains_from_identity),"inspect real envelope");
 auto prepared=need(prepare_native_catalog(catalog,text(request,"scenario_id"),envelope.identity.catalog),"exact selected native catalog");
 const auto reject=[&](const Bytes& broken,const StableId& name,const StableId& expected){auto before=need(world->checkpoint(),"prior bad-bank world");auto result=world->restore(broken);check(!result.ok&&result.error.original.code==expected,"wrong bad-bank rejection "+name+": "+result.error.original.code);check(before==need(world->checkpoint(),"after bad-bank world"),"bad bank replaced live world");write(root/(name+"-rejection.json"),boundary::obj({{"code",V{result.error.original.code}}}));};
 auto missing=envelope;missing.sections.erase(std::remove_if(missing.sections.begin(),missing.sections.end(),[](const auto& section){return section.domain=="production_disruptions";}),missing.sections.end());reject(need(encode_checkpoint(missing),"encode missing domain"),"missing-domain","CheckpointDomainMismatch");
 auto wrong=envelope;for(auto& section:wrong.sections)if(section.domain=="production_disruptions")section.codec_version=2;reject(need(encode_checkpoint(wrong),"encode wrong version"),"wrong-version","CheckpointDomainMismatch");
 WorldBundle damaged(prepared,need(decode_world_checkpoint(bank,*prepared),"decode original full bank"));damaged.production_disruptions.settlements.rows().front().second.remaining_yield_bp=10000;reject(need(encode_world_checkpoint(damaged),"encode changed loss"),"changed-loss","ProductionDisruptionSettlementMismatch");
 check(before_due.as<V::Dict>()&&last_step_ids>1,"actual production boundary required for late failure");WorldBundle risk(prepared,need(decode_world_checkpoint(before_due_bank,*prepared),"decode actual pre-production bank"));risk.common.state().next_instance_id=INT64_MAX-last_step_ids+1;auto valid=risk.validate();check(valid.ok,"late-ID risk typed world valid: "+valid.error.original.code);auto fault=create_resident_replay_session();auto loaded=fault->initialize_checkpoint(catalog,need(encode_world_checkpoint(risk),"encode natural late-ID candidate"));check(loaded.ok,"late-ID risk bank admitted: "+loaded.error.original.code);const auto prior=need(fault->checkpoint(),"late-ID before");auto failed=command(*fault,"advance");auto refused=need(std::move(failed),"late-ID transport").result;write(root/"late-id-rejection.json",refused);check(!boundary::get_bool(refused,"ok","late-ID receipt")&&text(refused,"code")=="InstanceIdOverflow","real late whole-World failure: "+json(refused));check(prior==need(fault->checkpoint(),"late-ID after"),"late ID changed whole World");save(*fault,root,"late-id-unchanged");
 write(root/"commands.json",V{trace});write(root/"result.json",boundary::obj({{"ok",V{true}},{"checks",V{checks}},{"real_world",V{true}},{"main_tested",V{false}},{"gui_tested",V{false}}}));std::cout<<"production disruptions real World money/material/window/cold/late-ID: "<<checks<<" checks PASS\n";return 0;
 }catch(const std::exception& error){if(!root.empty())write(root/"failure.json",boundary::obj({{"error",V{StableId{error.what()}}},{"checks",V{checks}},{"trace",V{trace}}}));std::cerr<<error.what()<<'\n';return 1;}}
